class SyncJob
{
    void Run(BlogContext context)
    {
        // Breaking change 4: EF 9 uses role-based API with patch/full-replace
        // semantics. Sync reads with tracking still work, but SaveChanges now
        // defaults to patch updates. No code change needed here.

        // Breaking change 5: Raw SQL using "Discriminator" must be updated
        // if not using the HasJsonPropertyName fix above. With the fix in
        // BlogContext, existing queries like:
        //   SELECT * FROM c WHERE c.Discriminator = 'Blog'
        // continue to work. Without it, they would need to change to:
        //   SELECT * FROM c WHERE c["$type"] = 'Blog'

        var blogs = context.Blogs.ToList();
        foreach (var b in blogs) { b.Name = b.Name.Trim(); }
        context.SaveChanges();
    }
}

